<template><ForgeDialog title="Markdown preview" description="Write documentation with a live rendered preview." eyebrow="WORKSPACE / CODE" wide @close="emit('close')"><div class="md-panel"><div class="md-toolbar"><button class="action-button" @click="openFile">Open .md</button><button class="action-button" @click="copy">Copy source</button></div><div class="md-columns"><textarea v-model="source" spellcheck="false" placeholder="# Project notes" /><article class="md-preview" v-html="rendered" /></div></div><template #footer><span class="website-help">HTML tags are disabled while rendering Markdown.</span><button class="action-button" @click="source=''">Clear</button></template></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import MarkdownIt from 'markdown-it'
import ForgeDialog from './ForgeDialog.vue'
import { dialog, fs, clipboard } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const source=ref('# PQT Forge\n\nWrite your notes here.'); const md=new MarkdownIt({html:false,linkify:true,typographer:true}); const rendered=computed(()=>md.render(source.value)); const openFile=async()=>{const r=await dialog.showOpenDialog({properties:['openFile'],filters:[{name:'Markdown',extensions:['md','markdown']}]});if(!r.canceled&&r.filePaths[0])source.value=await fs.readFile(r.filePaths[0])}; const copy=()=>clipboard.writeText(source.value)
</script>
<style scoped>.md-panel{display:grid;gap:10px}.md-toolbar{display:flex;gap:7px}.md-columns{display:grid;grid-template-columns:1fr 1fr;gap:12px;min-height:390px}.md-columns textarea{width:100%;resize:none;padding:12px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px/1.6 var(--pqt-font-mono)}.md-preview{overflow:auto;padding:16px;background:#f5f7f5;color:#18211f;border-radius:7px;line-height:1.6}.md-preview :deep(h1),.md-preview :deep(h2){margin:0 0 12px}.md-preview :deep(code){padding:2px 4px;background:#dfe8e5;border-radius:3px;font-family:var(--pqt-font-mono)}</style>
